-- ZuluAlpha's nights before tracking started (18 to 24 Nov 2026): the 5-minute CloudWatcher samples behind the history
-- table on its status page (conditions/history, the 168 hours it serves), taken while the Sun was down. They're weather
-- the observatory recorded, not polls of ours, so they're marked as backfilled and add nothing to remote_polls.
-- "clear" is their own observing limit, at most 20% estimated cloud, as in app/worker/remote.js.
alter table public.remote_weather add column backfilled boolean not null default false; -- imported from the site's own log

